insert into public.perpus_penulis (nama, jenis, "bioId", "bioEn", instagram, sumber) values
  ('Tere Liye', 'penulis', 'Nama pena Darwis, novelis Indonesia kelahiran Lahat, 1979, dan lulusan Universitas Indonesia. Memulai lewat Hafalan Shalat Delisa dan menulis lintas genre, dari drama keluarga hingga seri fantasi Bumi.', 'Pen name of Darwis, an Indonesian novelist born in Lahat in 1979 and a Universitas Indonesia graduate. He began with Hafalan Shalat Delisa and writes across genres, from family drama to the Bumi fantasy series.', 'tereliyewriter', 'https://www.suara.com/news/2023/02/23/140037/mengenal-siapa-tere-liye-penulis-novel-bumi-yang-heboh-dikritik-netizen'),
  ('Felix Y Siauw', 'penulis', 'Penulis dan pendakwah kelahiran Palembang, 1984, lulusan Institut Pertanian Bogor. Karyanya antara lain Beyond the Inspiration, Muhammad Al-Fatih 1453, dan Udah Putusin Aja.', 'An author and preacher born in Palembang in 1984, and a graduate of Bogor Agricultural University. His books include Beyond the Inspiration, Muhammad Al-Fatih 1453, and Udah Putusin Aja.', null, 'https://en.wikipedia.org/wiki/Felix_Siauw'),
  ('Harun Yahya', 'penulis', 'Nama pena Adnan Oktar, penulis asal Turki yang dikenal lewat buku-buku bertema keimanan dan penciptaan.', 'Pen name of Adnan Oktar, a Turkish author known for books on faith and creation.', null, 'https://en.wikipedia.org/wiki/Adnan_Oktar'),
  ('Sir Arthur Conan Doyle', 'penulis', 'Penulis Skotlandia (1859–1930) dan seorang dokter, pencipta detektif Sherlock Holmes.', 'Scottish author and physician (1859–1930), the creator of detective Sherlock Holmes.', null, 'https://en.wikipedia.org/wiki/Arthur_Conan_Doyle'),
  ('J.S. Khairen', 'penulis', 'Jombang Santani Khairen, novelis kelahiran Sumatera Barat, 1991. Dikenal lewat seri Kami (Bukan), termasuk Kami (Bukan) Sarjana Kertas.', 'Jombang Santani Khairen, a novelist born in West Sumatra in 1991, known for the Kami (Bukan) series, including Kami (Bukan) Sarjana Kertas.', 'js_khairen', 'https://www.gramedia.com/best-seller/buku-karya-js-khairen'),
  ('Andrea Hirata', 'penulis', 'Novelis asal Belitung, dikenal lewat Laskar Pelangi (2005) yang berangkat dari masa kecilnya dan diangkat ke layar lebar pada 2008.', 'A novelist from Belitung, known for Laskar Pelangi (2005), drawn from his childhood and adapted into a film in 2008.', null, 'https://en.wikipedia.org/wiki/Andrea_Hirata'),
  ('Robert t kiyosaki', 'penulis', 'Pengusaha dan penulis Amerika kelahiran 1947, dikenal lewat seri keuangan pribadi Rich Dad Poor Dad.', 'American businessman and author born in 1947, known for the Rich Dad Poor Dad personal finance series.', null, 'https://en.wikipedia.org/wiki/Robert_Kiyosaki'),
  ('A.Fuadi', 'penulis', 'Ahmad Fuadi, alumnus Pondok Modern Gontor asal Maninjau, mantan wartawan TEMPO dan VOA. Penulis trilogi Negeri 5 Menara yang diadaptasi menjadi film.', 'Ahmad Fuadi, a Gontor alumnus from Maninjau and former TEMPO and VOA journalist, author of the Negeri 5 Menara trilogy, which was adapted into a film.', 'afuadi', 'https://www.gramedia.com/products/negeri-5-menara-1'),
  ('Habiburrahman El Shirazy', 'penulis', 'Dikenal sebagai Kang Abik, novelis dan pendakwah lulusan Universitas Al-Azhar, Kairo. Novelnya Ayat-Ayat Cinta (2004) membuatnya dikenal luas.', 'Known as Kang Abik, a novelist and preacher who graduated from Al-Azhar University in Cairo. His novel Ayat-Ayat Cinta (2004) brought him wide recognition.', null, 'https://en.wikipedia.org/wiki/Habiburrahman_El_Shirazy'),
  ('Salim A Fillah', 'penulis', 'Penulis buku-buku dakwah dan sejarah Islam yang banyak diterbitkan Pro U Media.', 'An author of Islamic outreach and history books, many published by Pro U Media.', null, 'https://moraref.kemenag.go.id/documents/article/98077985952855763'),
  ('ALFIALGHAZI', 'penulis', 'Nama pena Alfi Syahri Ramadhan, penulis Maaf Tuhan, Aku Hampir Menyerah dan Ya Allah, Aku Pulang.', 'Pen name of Alfi Syahri Ramadhan, author of Maaf Tuhan, Aku Hampir Menyerah and Ya Allah, Aku Pulang.', null, 'https://www.gramedia.com/best-seller/buku-maaf-tuhan-aku-hampir-menyerah/'),
  ('Brian Khrisna', 'penulis', 'Penulis asal Bandung kelahiran 1992. Novelnya Seporsi Mie Ayam Sebelum Mati menjadi sangat laris dan diadaptasi menjadi film.', 'A writer from Bandung born in 1992. His novel Seporsi Mie Ayam Sebelum Mati became a major bestseller and was adapted into a film.', 'brian.khrisna', 'https://www.idntimes.com/hype/entertainment/novel-seporsi-mie-ayam-sebelum-mati-dibuat-film-mulai-syuting-april-2026-00-hwff8-26x4g3'),
  ('Leila S. Chudori', 'penulis', 'Penulis dan wartawan Indonesia, dikenal lewat novel Pulang dan Laut Bercerita.', 'An Indonesian author and journalist, known for the novels Pulang and Laut Bercerita.', 'leilachudori', 'https://www.gramedia.com/blog/profil-leila-s-chudori-buku-bukunya-karier-menulis/amp/'),
  ('Asma Nadia', 'penulis', 'Novelis Indonesia, dikenal lewat Assalamualaikum Beijing dan Catatan Hati Seorang Istri.', 'An Indonesian novelist, known for Assalamualaikum Beijing and Catatan Hati Seorang Istri.', 'asmanadia', 'https://www.idntimes.com/hype/entertainment/kelahiran-cucu-penulis-asma-nadia-c1c2-01-hf9n1-4tqg33'),
  ('Mark Manson', 'penulis', 'Penulis Amerika, dikenal lewat buku The Subtle Art of Not Giving a F*ck.', 'American author, known for The Subtle Art of Not Giving a F*ck.', null, null),
  ('James Clear', 'penulis', 'Penulis Amerika, dikenal lewat Atomic Habits tentang membangun kebiasaan kecil.', 'American author, known for Atomic Habits, on building small habits.', null, 'https://jamesclear.com/about'),
  ('Morgan Housel', 'penulis', 'Penulis keuangan dan mitra di Collaborative Fund, dikenal lewat The Psychology of Money.', 'A finance writer and partner at Collaborative Fund, known for The Psychology of Money.', null, 'https://www.penguinrandomhouse.com/authors/2244345/morgan-housel/'),
  ('Charles Duhigg', 'penulis', 'Jurnalis dan penulis Amerika, dikenal lewat The Power of Habit.', 'American journalist and author, known for The Power of Habit.', null, 'https://en.wikipedia.org/wiki/Charles_Duhigg'),
  ('Ibnu Qayyim Al-Jauziyyah', 'penulis', 'Ulama Damaskus abad ke-14 (1292–1350), murid Ibnu Taimiyah, dengan karya luas dalam fikih dan penyucian jiwa.', 'A 14th-century Damascene scholar (1292–1350) and student of Ibn Taymiyyah, with wide-ranging works on law and spirituality.', null, 'https://en.wikipedia.org/wiki/Ibn_Qayyim_al-Jawziyya'),
  ('Ibnu Hajar Al-Asqalani', 'penulis', 'Ulama hadis Mesir (1372–1449), penulis Fath al-Bari, syarah Shahih al-Bukhari.', 'An Egyptian hadith scholar (1372–1449), author of Fath al-Bari, a commentary on Sahih al-Bukhari.', null, 'https://en.wikipedia.org/wiki/Ibn_Hajar_al-Asqalani'),
  ('Oh Su Hyang', 'penulis', 'Pengajar komunikasi asal Korea Selatan, dikenal lewat buku Bicara Itu Ada Seninya.', 'A South Korean communication lecturer, known for the book Bicara Itu Ada Seninya.', null, null),
  ('george orwell', 'penulis', 'Penulis Inggris (1903–1950), dikenal lewat Animal Farm dan Nineteen Eighty-Four.', 'English author (1903–1950), known for Animal Farm and Nineteen Eighty-Four.', null, 'https://en.wikipedia.org/wiki/George_Orwell'),
  ('Orwell', 'penulis', 'Penulis Inggris (1903–1950), dikenal lewat Animal Farm dan Nineteen Eighty-Four.', 'English author (1903–1950), known for Animal Farm and Nineteen Eighty-Four.', null, 'https://en.wikipedia.org/wiki/George_Orwell'),
  ('Henry Manampiring', 'penulis', 'Penulis Indonesia, dikenal lewat Filosofi Teras yang mengenalkan Stoisisme kepada pembaca muda.', 'An Indonesian author, known for Filosofi Teras, which introduced Stoicism to young readers.', null, null),
  ('Ichiro Kishimi & Fumitake Koga', 'penulis', 'Filsuf dan penulis Jepang di balik The Courage to Be Disliked, yang mengulas psikologi Adler.', 'The Japanese philosopher and writer behind The Courage to Be Disliked, which explores Adlerian psychology.', null, null),
  ('Simon Sinek', 'penulis', 'Penulis dan pembicara, dikenal lewat Start With Why.', 'An author and speaker, known for Start With Why.', null, 'https://en.wikipedia.org/wiki/Simon_Sinek'),
  ('Tan Malaka', 'penulis', 'Tokoh pergerakan dan Pahlawan Nasional Indonesia (1897–1949), penulis Madilog.', 'An Indonesian independence figure and National Hero (1897–1949), author of Madilog.', null, 'https://en.wikipedia.org/wiki/Tan_Malaka'),
  ('ECKHART TOLLE', 'penulis', 'Penulis spiritual kelahiran Jerman, dikenal lewat The Power of Now.', 'A German-born spiritual author, known for The Power of Now.', null, 'https://en.wikipedia.org/wiki/Eckhart_Tolle'),
  ('Paulo Freire', 'penulis', 'Pendidik dan filsuf Brasil (1921–1997), penulis Pendidikan Kaum Tertindas.', 'Brazilian educator and philosopher (1921–1997), author of Pedagogy of the Oppressed.', null, 'https://en.wikipedia.org/wiki/Paulo_Freire'),
  ('Jostin Gaarder', 'penulis', 'Jostein Gaarder, penulis Norwegia kelahiran 1952, dikenal lewat Dunia Sophie.', 'Jostein Gaarder, a Norwegian author born in 1952, known for Sophie''s World.', null, 'https://en.wikipedia.org/wiki/Jostein_Gaarder'),
  ('Herman Melville', 'penulis', 'Novelis Amerika (1819–1891), penulis Moby-Dick.', 'American novelist (1819–1891), author of Moby-Dick.', null, 'https://en.wikipedia.org/wiki/Herman_Melville'),
  ('Agus Noor', 'penulis', 'Cerpenis dan penulis naskah lakon Indonesia.', 'An Indonesian short story writer and playwright.', null, null),
  ('Paulo Coelho', 'penulis', 'Novelis Brasil kelahiran 1947, dikenal lewat Sang Alkemis.', 'A Brazilian novelist born in 1947, known for The Alchemist.', null, 'https://en.wikipedia.org/wiki/Paulo_Coelho'),
  ('Penerbit Andi', 'penerbit', null, null, null, null)
